<script>

import languages from "@/store/languages";
import ScreenCanvas from "@/components/ScreenCanvas";
import {getScreenshots, addScreenshots, uploadGoogle, updateScreenshots} from '../../api/screenshot'
import FileSaver from 'file-saver'
import ScreenPreview from "@/components/ScreenPreview.vue";
import JSZip from "jszip";

export default {
  components: {ScreenPreview, ScreenCanvas},
  data() {
    return {
      isAddScreen: true,
      isLoading: false,
      addDialogVisible: false,
      isUploadLoading: false,
      languagesOptions: [],
      languagesSelected: "EN",
      pageData: [],
      selectedFiles: [],
      screenshotFrom: {
        projectId: this.$route.params.id,
        transId: 0,
        ssAppUrl: '',
        ssBgColor: ''
      },

    };
  },
  computed: {

  },
  watch: {
    projectData(newVal, oldVal) {
      if (this.$route.params.id == this.$store.state.tab.projectData.projectId) {
        this.refreshPage()
      }
    },
    languagesSelected(newVal, oldVal) {
      if (newVal != oldVal) {
        this.pageData = this.pageData
      }
    }
  },
  mounted() {
    this.refreshPage()
  },
  methods: {

    refreshPage() {
      // 构建语言选择列表
      const projectData = this.$store.state.tab.projectData;
      if (this.$route.params.id != projectData.projectId) {
        // 没有基础数据，暂时不处理
        return
      }

      const set = []
      projectData.languages.split(",").forEach((item) => {
        console.log(item)
        set.push(item.trim())
      });

      this.languagesOptions = []

      Object.keys(languages.state.allLanguages).forEach((item) => {
        if (set.includes(languages.state.languageKey[item])) {
          this.languagesOptions.push({
            label: languages.state.allLanguages[item],
            value: languages.state.languageKey[item],
          })
        }
      })

      const request = {
        "projectId": this.$route.params.id
      }
      getScreenshots(request).then((data) => {
        this.isLoading = false
        console.log(data)
        this.pageData = data.data
      })
    },
    getScreenUrl(lang, oriUrl, index) {
      for (var i = 0; i < files.length; i++) {
        if (files[i].webkitRelativePath.contains(lang + "/" + index + ".png"))
        return
        console.log('文件名:', );
      }
    },

    getLanguageParam(data, key) {
      let result = ""
      console.log(key)
      Object.keys(languages.state.languageKey).forEach((item) => {
        if (key === languages.state.languageKey[item]) {
          // TODO ID 错误，找不到语言，就会有问题
          result = data.transKeys[item]
        }
      })
      return result
    },
    getLanguageName() {
      return languages.state.languages[this.languagesSelected]
    },
    handleSwap(prev, next) {
      if (prev == null || next == null) return
      let tmpId = prev.ssId
      prev.ssId = next.ssId
      next.ssId = tmpId

      console.log(prev.ssId, next.ssId)
      updateScreenshots(prev).then((data) => {
        console.log(data)
        updateScreenshots(next).then((data) => {
          console.log(data)
          let tmp = {}
          tmp.transId = prev.transId
          tmp.ssAppUrl = prev.ssAppUrl
          tmp.ssBgColor = prev.ssBgColor

          prev.transId = next.transId
          prev.ssAppUrl = next.ssAppUrl
          prev.ssBgColor = next.ssBgColor

          next.transId = tmp.transId
          next.ssAppUrl = tmp.ssAppUrl
          next.ssBgColor = tmp.ssBgColor
        })
      })

    },
    handAddScreenshot() {
      if (this.isAddScreen) {
        addScreenshots(this.screenshotFrom).then((data) => {
          console.log(data)
          this.addDialogVisible = false
        })
      } else {
        updateScreenshots(this.screenshotFrom).then((data) => {
          console.log(data)
          this.addDialogVisible = false
        })
      }
    },
    uploadGooglePlayAll() {
      const projectData = this.$store.state.tab.projectData;
      const set = []
      projectData.languages.split(",").forEach((item) => {
        set.push(item.trim())
      });
      console.log(set)
      this.uploadGooglePlay(set, 0)
    },
    uploadGooglePlay(languages, index) {
      let language = languages[index]
      this.isUploadLoading = true
      let files = new Array(this.$refs['screenRefs_' + language].length)

      for (let i = 0; i < this.$refs['screenRefs_' + language].length; i++) {
        files[i] = this.$refs['screenRefs_' + language][i].exportImages()
      }

      let formData = new FormData()
      Array.from(files).forEach(file => {
        formData.append("files", file)
        console.log(file)
      })
      formData.append("projectId", this.$route.params.id)
      formData.append("languages", language)


      uploadGoogle(formData).then((data) => {
        this.isUploadLoading = false
        console.log(data)
        if (index < languages.length - 1) {
          this.uploadGooglePlay(languages, index + 1)
        }
      })
    },
    formatImageUrl(data) {
      return this.require("/assets/logo.png")
    },

    setLocalFiles(files) {
      for (let myitem of this.languagesOptions) {
        let language = myitem.value

        let canvasArray = this.$refs['screenRefs_' + language]
        if (canvasArray != null) {
          for (let j = 0; j < this.$refs['screenRefs_' + language].length; j++) {
            let file = this.findFileInFiles(files, "captures/" + language +"/" + j + ".png")
            if (file != null) {
              this.$refs['screenRefs_' + language][j].screenBlob = file
            }
          }
        }
      }
    },

    findFileInFiles(files, fileName) {
      for (let i = 0; i < files.length; i++) {
        const file = files[i];
        if (file.webkitRelativePath === fileName) {
          return file;
        }
      }
      return null; // 如果未找到匹配的文件则返回 null
    },
    loadImages() {

      var input = document.createElement('input');
      input.type = 'file';
      input.webkitdirectory = true;
      input.directory = true;

      let wrapperThis = this

      input.addEventListener('change', function(e) {
        var files = e.target.files;
        this.selectedFiles = files

        wrapperThis.setLocalFiles(files)


        // for (var i = 0; i < files.length; i++) {
        //   console.log('文件名:', files[i].webkitRelativePath);
        // }
      });
      input.click()
    },
    downloadShell() {
      this.isOutputLoading = true
      let zip = new JSZip()



      // translate
      for (let myitem of this.languagesOptions) {
        let lang = myitem.value
        let folder = lang
        for (let i = 0; i < this.$refs['screenRefs_' + lang].length; i++) {
          let file = this.$refs['screenRefs_' + lang][i].exportImages()
          zip.file(folder + '/images/phoneScreenshots/' + i + '_' +file.name, file )
        }
      }


      // download
      zip.generateAsync({ type: 'blob' }).then(content => {
        this.isOutputLoading = false
        // 使用 FileSaver.js 下载 ZIP 文件
        FileSaver.saveAs(content, 'AppLocalize_Screenshots.zip');
      });
    }

  },
}
</script>


